[[ ## document ## ]]
{
  "title": "Blue Fir Restaurant Group Q1/Q2 Payroll and Quarterly Filing Checklist",
  "path": "engagements/blue-fir-restaurant-group/payroll/q1-q2-filing-checklist.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "Blue Fir Restaurant Group — Q1/Q2 Payroll and Quarterly Filing Checklist"
      },
      {
        "kind": "paragraph",
        "text": "Prepared by Sylvia Nakamura, Payroll Specialist, following the tax group huddle on Blue Fir payroll scope and withholding questions. This checklist covers the post-huddle filing steps for Q1 and Q2 2025 quarterly employment filings."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "1. Q1 Filing Status"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Confirm Q1 federal Form 941 was filed and payment made by the April 30 deadline (already completed per payroll folder).",
          "Confirm Q1 Oregon withholding return was filed and payment made; note that a Q1 amendment was filed in May to correct a tip-allocation error — the amended filing and payment confirmation are in the payroll folder.",
          "Verify the Q1 state amendment is reflected in the payroll system's withholding summary; flag any discrepancy with the state before Q2 filing.",
          "Review any state notice received for Q1 — if a notice arrived regarding Q1, it almost certainly crossed in the mail with the May amendment; respond only after confirming the amendment was processed."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "2. Q2 Filing Preparation"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Pull Q2 payroll registers from the payroll system for all Blue Fir locations (including tip allocation by establishment).",
          "Reconcile gross wages, federal taxable wages, Social Security wages, Medicare wages, and federal withholding to the general ledger.",
          "Reconcile Oregon taxable wages and Oregon withholding to the general ledger.",
          "Verify tip allocation amounts match the tip allocation worksheet and that no Q1 error is repeated in Q2.",
          "Prepare Q2 federal Form 941 and Oregon quarterly withholding return.",
          "Schedule internal review and partner sign-off before the filing deadlines (July 31 for federal and state).",
          "Submit Q2 filings and schedule payment confirmations."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "3. Filing Confirmation and Documentation"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Save copies of all Q1 and Q2 filings (including the Q1 amendment) in the Blue Fir payroll folder with consistent naming: BlueFir_Q1_941_2025.pdf, BlueFir_Q1_OR_2025_amended.pdf, BlueFir_Q2_941_2025.pdf, BlueFir_Q2_OR_2025.pdf.",
          "Record payment confirmation numbers (bank or state portal) for each filing in the filing log.",
          "Cross-reference the filing log with the payroll system's 'filed' status for each period.",
          "Note any open items (e.g., pending state notice response) in the payroll folder's status memo."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "4. Post-Huddle Action Items"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Confirm with Theo that the Q1 amendment confirmation is filed in the payroll folder (he confirmed his prep in the huddle).",
          "Flag to Theo any Q2 tip-allocation figures that differ from the Q1 corrected approach.",
          "Hold the Q2 filings for internal review by July 15, 2025.",
          "Log this checklist in the engagement file as the post-huddle filing checklist."
        ]
      },
      {
        "kind": "paragraph",
        "text": "Prepared by Sylvia Nakamura, Payroll Specialist. For questions, contact the payroll team via the shared engagement mailbox."
      }
    ]
  }
}
